  ('00000000-0000-4000-8000-000000002027', 'WED-004', '상견례 날짜 조율', 'family', null, '2026-11-30', 'todo', 'high', 'couple', '양가 일정을 확인하고 2026년 12월~2027년 1월 진행을 목표로 한다.', null, null, null, null, null),
  ('00000000-0000-4000-8000-000000002027', 'WED-005', '야외 스냅 촬영 분위기 결정', 'outdoor_shoot', null, '2026-11-30', 'todo', 'medium', 'couple', '공원·숲·자연광, 도심·건축물·거리, 꽃과 정원 중 선호 분위기를 정한다.', null, null, null, null, null),
  ('00000000-0000-4000-8000-000000002027', 'WED-006', '신혼여행 시기 및 목적지 구체화', 'honeymoon', null, '2026-11-30', 'todo', 'high', 'couple', '캄보디아 선교 이후인 2027년 9월 추석 연휴 활용 여부와 포르투갈·스페인 일정을 검토한다.', null, null, null, null, null),
  ('00000000-0000-4000-8000-000000002027', 'WED-007', '실내 촬영 의상 1차 확정', 'indoor_shoot', null, '2026-12-15', 'todo', 'high', 'couple', '개인 의상 후보를 좁히고 필요한 구매·대여 여부를 결정한다.', null, null, null, null, null),
  ('00000000-0000-4000-8000-000000002027', 'WED-008', '촬영 소품 준비', 'indoor_shoot', null, '2026-12-31', 'todo', 'medium', 'couple', '부케, 구두, 액세서리, 헤어 장식 등 촬영 소품을 준비한다.', null, null, null, null, null),
  ('00000000-0000-4000-8000-000000002027', 'WED-009', '실내 촬영 의상 최종 구성', 'indoor_shoot', null, '2026-12-31', 'todo', 'high', 'couple', '의상별 착장 조합과 신랑 의상 톤을 확정한다.', null, null, null, null, null),
  ('00000000-0000-4000-8000-000000002027', 'WED-010', '상견례 진행', 'family', null, '2027-01-31', 'todo', 'high', 'couple', '상견례를 진행한다. 실제 날짜는 양가 일정에 맞춰 확정한다.', null, null, null, null, null),
  ('00000000-0000-4000-8000-000000002027', 'WED-011', '실내 웨딩 촬영 진행', 'indoor_shoot', null, '2027-02-15', 'todo', 'critical', 'couple', '561스튜디오에서 촬영한다. 1월 말~2월 초를 우선 목표로 하며, 2월 15일까지 완료하는 일정이다.', null, null, '561스튜디오', null, null),
  ('00000000-0000-4000-8000-000000002027', 'WED-012', '혼주 의상 업체 알아보기 및 예약', 'family', null, '2027-01-31', 'todo', 'medium', 'couple', '양가 혼주 한복·정장 업체를 알아보고 예약한다.', null, null, null, null, null),
  ('00000000-0000-4000-8000-000000002027', 'WED-013', '사회자 및 축가 섭외', 'ceremony', null, '2027-01-31', 'todo', 'medium', 'couple', '사회자와 축가 담당자를 정하고 가능 여부를 확인한다.', null, null, null, null, null),
  ('00000000-0000-4000-8000-000000002027', 'WED-014', '모바일 청첩장 업체 조사', 'invitation', null, '2027-01-31', 'todo', 'medium', 'couple', '모바일 청첩장 제작 업체와 디자인 옵션을 조사한다.', null, null, null, null, null),
  ('00000000-0000-4000-8000-000000002027', 'WED-015', '실내 촬영 사진 셀렉 및 보정 요청', 'indoor_shoot', null, '2027-02-28', 'todo', 'high', 'couple', '사진을 고르고 보정 방향 및 수정 요청사항을 정리한다.', null, null, null, null, null),
  ('00000000-0000-4000-8000-000000002027', 'WED-016', '야외 촬영 장소 후보 2~3곳 선정', 'outdoor_shoot', null, '2027-02-15', 'todo', 'medium', 'couple', '촬영 분위기에 맞는 장소 후보를 찾고 이동 동선을 검토한다.', null, null, null, null, null),
