  ('00000000-0000-4000-8000-000000002027', 'WED-020', '혼주 메이크업 예약', 'family', null, '2027-02-28', 'todo', 'medium', 'couple', '양가 혼주 메이크업 일정과 업체를 예약한다.', null, null, null, null, null),
  ('00000000-0000-4000-8000-000000002027', 'WED-021', '신혼여행 항공권 및 숙소 예약', 'honeymoon', null, '2027-03-31', 'todo', 'high', 'couple', '포르투갈 체류를 스페인보다 길게 하는 약 12박 14일 여행안을 기준으로 예약한다. 실제 추석 연휴 및 항공 일정을 확인한다.', null, null, null, null, null),
  ('00000000-0000-4000-8000-000000002027', 'WED-022', '실내 촬영 보정본 수령', 'indoor_shoot', null, '2027-03-15', 'todo', 'critical', 'couple', '모바일 청첩장 제작에 사용할 보정 사진을 확보한다.', null, null, null, null, null),
