  ('00000000-0000-4000-8000-000000002027', 'WED-024', '모바일 청첩장 문구 및 정보 정리', 'invitation', null, '2027-03-20', 'todo', 'high', 'couple', '초대 문구, 예식 정보, 지도, 교통 안내, 연락처 등을 준비한다.', null, null, null, null, null),
  ('00000000-0000-4000-8000-000000002027', 'WED-025', '하객 명단 초안 작성', 'guest_management', null, '2027-03-31', 'todo', 'medium', 'couple', '양가 및 신랑·신부 측 하객 명단을 구분해 작성한다.', null, null, null, null, null),
  ('00000000-0000-4000-8000-000000002027', 'WED-026', '야외 스냅 촬영일 및 예비일 확정', 'outdoor_shoot', null, '2027-03-25', 'todo', 'high', 'couple', '친구와 촬영 날짜·시간을 확정하고 우천 등 날씨 변수에 대비한 예비일을 정한다.', null, null, null, null, null),
  ('00000000-0000-4000-8000-000000002027', 'WED-027', '야외 스냅 최종 점검', 'outdoor_shoot', null, '2027-03-31', 'todo', 'medium', 'couple', '날씨, 개화 상황, 의상, 장소, 촬영 준비물을 확인한다.', null, null, null, null, null),
