  ('00000000-0000-4000-8000-000000002027', 'WED-029', '모바일 청첩장 최종 제작 및 공개', 'invitation', '2027-04-10', '2027-04-15', 'todo', 'critical', 'couple', '실내 촬영 보정본을 중심으로 먼저 공개한다. 야외 사진은 추후 추가할 수 있다.', null, null, null, null, null),
  ('00000000-0000-4000-8000-000000002027', 'WED-030', '모바일 청첩장 전달 및 하객 안내', 'guest_management', null, '2027-04-30', 'todo', 'high', 'couple', '친척, 지인, 직장 동료 등에게 청첩장을 전달하고 참석 여부를 관리한다.', null, null, null, null, null),
  ('00000000-0000-4000-8000-000000002027', 'WED-031', '야외 촬영 사진 셀렉 및 보정', 'outdoor_shoot', null, '2027-04-20', 'todo', 'low', 'couple', '사진을 셀렉하고 필요하면 모바일 청첩장이나 개인 기록에 추가한다.', null, null, null, null, null),
  ('00000000-0000-4000-8000-000000002027', 'WED-032', '본식 드레스 최종 가봉', 'ceremony', null, '2027-05-15', 'todo', 'high', 'bride', '본식 드레스 핏과 수선 사항을 최종 확인한다.', null, null, null, null, null),
  ('00000000-0000-4000-8000-000000002027', 'WED-033', '본식 헤어·메이크업 스타일 최종 확정', 'ceremony', null, '2027-05-15', 'todo', 'high', 'bride', '헤어와 메이크업 레퍼런스 및 요청사항을 정리한다.', null, null, null, null, null),
  ('00000000-0000-4000-8000-000000002027', 'WED-034', '부케 및 본식 소품 확정', 'ceremony', null, '2027-05-15', 'todo', 'medium', 'couple', '부케, 구두, 액세서리 등 본식 소품을 확정한다.', null, null, null, null, null),
  ('00000000-0000-4000-8000-000000002027', 'WED-035', '혼주 의상·메이크업 최종 확인', 'family', null, '2027-05-15', 'todo', 'high', 'couple', '양가 혼주 의상, 메이크업 예약 및 당일 시간을 확인한다.', null, null, null, null, null),
  ('00000000-0000-4000-8000-000000002027', 'WED-036', '예식장 보증 인원 및 식대 확인', 'venue', null, '2027-05-15', 'todo', 'critical', 'couple', '최종 예상 하객 수를 취합하고 예식장 보증 인원·식대·마감일을 확인한다.', null, null, '아펠가모 광화문', null, null),
  ('00000000-0000-4000-8000-000000002027', 'WED-037', '본식 스냅·영상 업체 최종 전달', 'ceremony', null, '2027-05-15', 'todo', 'medium', 'couple', '촬영 요청 컷, 가족 사진, 진행 순서 및 업체 도착 시간을 공유한다.', null, null, null, null, null),
  ('00000000-0000-4000-8000-000000002027', 'WED-038', '사회자·축가·식순·음악 최종 확정', 'ceremony', null, '2027-05-20', 'todo', 'high', 'couple', '사회자 대본, 축가, 입장곡, 행진곡, 식순을 최종 확인한다.', null, null, null, null, null),
