  ('00000000-0000-4000-8000-000000002027', 'WED-040', '신혼여행 서류 및 짐 준비', 'honeymoon', null, '2027-05-31', 'todo', 'medium', 'couple', '여권 유효기간, 항공·숙소 예약 내역, 여행자 보험 및 준비물을 확인한다.', null, null, null, null, null),
  ('00000000-0000-4000-8000-000000002027', 'WED-041', '본식 최종 준비물 및 동선 점검', 'ceremony', null, '2027-06-04', 'todo', 'critical', 'couple', '반지·예물, 드레스·소품, 혼주 및 가족 도착 시간, 당일 이동 동선과 준비물을 최종 확인한다.', null, null, null, null, null),
  ('00000000-0000-4000-8000-000000002027', 'WED-042', '결혼식', 'ceremony', null, '2027-06-05', 'todo', 'critical', 'couple', '아펠가모 광화문에서 12:30 예식을 진행한다.', null, null, '아펠가모 광화문', null, null),
  ('00000000-0000-4000-8000-000000002027', 'WED-043', '캄보디아 선교', 'post_wedding', '2027-08-12', '2027-08-16', 'planned', 'medium', 'couple', '2027년 8월 12일~16일 예정된 선교 일정.', null, null, null, null, null),
  ('00000000-0000-4000-8000-000000002027', 'WED-044', '신혼여행 출발', 'honeymoon', '2027-09-01', null, 'tentative', 'medium', 'couple', '2027년 9월 추석 연휴 활용을 검토한다. 실제 날짜와 연휴·항공편은 별도 확인 후 확정한다.', null, null, null, null, null),
  ('00000000-0000-4000-8000-000000002027', 'WED-045', '실내 촬영 헤어·메이크업 확정', 'indoor_shoot', null, null, 'todo', 'high', 'bride', '촬영일 3주 전까지 헤어·메이크업 스타일과 담당을 확정한다. 마감일은 실내 촬영일 확정 시 자동 계산된다.', null, null, null, null, '구현 노트의 상대 마감일 규칙(3주 전)에 따라 추가된 작업'),
  ('00000000-0000-4000-8000-000000002027', 'WED-046', '실내 촬영 최종 점검', 'indoor_shoot', null, null, 'todo', 'high', 'couple', '촬영일 1주 전 의상·소품·헤어·메이크업·이동 동선을 최종 점검한다. 마감일은 실내 촬영일 확정 시 자동 계산된다.', null, null, null, null, '구현 노트의 상대 마감일 규칙(1주 전)에 따라 추가된 작업');
